function runController(args,optimized=false,pass=true,env=process.env,contractOverride=null){
  const pythonArgs=[...(optimized?['-O']:[]),'-B'];
  if(contractOverride) pythonArgs.push('-c',PY_CONTRACT_OVERRIDE_RUNNER,...args);
  else pythonArgs.push(FILE.controller,...args);
  const r=spawnSync('python',pythonArgs,{cwd:ROOT,encoding:'utf8',windowsHide:true,env,input:contractOverride?JSON.stringify(contractOverride):undefined});
  assert.notEqual(r.status,null,`${args}: did not exit`);
  const out=jsonOutput(r,`${optimized?'opt ':''}${args.join(' ')}`);
  if(pass){assert.equal(r.status,0,r.stderr||r.stdout);assert.notEqual(out.status,'FAIL_CLOSED');}
  else{assert.notEqual(r.status,0,`${args} unexpectedly passed`);assert.equal(out.status,'FAIL_CLOSED');assert.deepEqual([out.sourceRequests,out.routeDiscoveryRequests,out.censusRequests,out.captureRequests,out.aiRuns],[0,0,0,0,0]);}
  return out;
}
function strictGovSyntax(input){
  try {
    if(/[\x00-\x20\x7f]/.test(input) || /%(?![0-9A-Fa-f]{2})/.test(input)) return false;
    const u=new URL(input);
    if(u.protocol!=='https:'||u.username||u.password||u.hash||u.search) return false;
    if(u.port&&u.port!=='443') return false;
    const host=u.hostname.toLowerCase().replace(/\.$/,'');
    if(!/^[a-z0-9.-]+$/.test(host)||!host.endsWith('.gov')||net.isIP(host)) return false;
    return true;
  } catch { return false; }
}

