function replacePythonCanonicalOracle(text,name,value){
  const start=text.indexOf(`${name} = (`); assert.notEqual(start,-1,`${name}: Python assignment missing`);
  const end=text.indexOf('\n)',start); assert.notEqual(end,-1,`${name}: Python assignment end missing`);
  const b64=canonicalBytes(value).toString('base64');
  const body=b64.match(/.{1,100}/g).map(part=>`    "${part}"`).join('\n');
  return `${text.slice(0,start)}${name} = (\n${body}\n)${text.slice(end+2)}`;
}
function replaceAllLiteral(text,oldValue,newValue){
  if(oldValue===newValue) return text;
  assert.equal(typeof oldValue,'string'); assert.equal(typeof newValue,'string');
  return text.includes(oldValue)?text.split(oldValue).join(newValue):`${text}\n# NODE_REPIN_LITERAL ${oldValue} -> ${newValue}`;
}
function setPinnedCanonical(g,stem,value){
  const raw=canonicalBytes(value);
  g[`${stem}CanonicalUtf8Base64`]=raw.toString('base64');
  g[`${stem}Bytes`]=raw.length;
  g[`${stem}Sha256`]=sha256(raw);
}
