  assert.equal(r.parserUsesOnlyAnchorHrefNeverTitleOrSnippet,true); assert.equal(r.candidateLimitBeforeFilter,64); assert.equal(r.crossThemeOwnershipOrCandidateSuppressionForbidden,true); assert.equal(r.sameCanonicalUrlMayOccupyValidationSlotForMultipleThemes,true);
